function travelPlanner(members, destination, tripType, days, hotel) {
    let options = ["budget", "activity", "food", "scenery", "historic"];

    const isPreApproved = members.some(m => m.preApproved);
    const isChina = destination === "China";
    const isHiking = tripType === "hiking";

    if (isPreApproved && isChina && isHiking) {
        return {
            hotel: hotel || "Grand Hotel",
            days: days || 10,
            destination: destination,
            tripType: tripType,
            options: options
        };
    }
}
